insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('past-rule', 'en-c3-grammar', 'Past Simple qaydası', 'Past Simple keçmişdə bitmiş işi bildirir. Gəl qaydanı öyrənək!', null, '[{"heading":"Past Simple nədir?","body":"Keçmişdə bitmiş işi bildirir: I played yesterday. Çox vaxt ''yesterday'', ''last week'', ''ago'' sözləri ilə işlənir."},{"heading":"Qaydalı fellər: -ed","body":"Əksər fellərə -ed əlavə olunur: play → played, visit → visited, help → helped. Bütün şəxslərdə eynidir (I/he/we played)."},{"heading":"Qaydasız fellər","body":"Bəzi fellər dəyişir: go → went, see → saw, eat → ate, have → had. Bunları əzbərləmək lazımdır."}]'::jsonb, 0),
  ('past-vocab', 'en-c3-vocab', 'Gündəlik fellər II (8 söz)', 'Keçmişdə görülən işləri bildirən 8 yeni fel öyrənək.', null, '[{"heading":"Yeni sözlər (8 fel)","body":"visit — ziyarət etmək · help — kömək etmək · clean — təmizləmək · wash — yumaq · walk — gəzmək · talk — danışmaq · want — istəmək · call — zəng etmək"},{"heading":"Məsləhət","body":"Bu fellər qaydalıdır — keçmişdə -ed alır: visited, helped, cleaned... Bir cümlədə xatırla: I helped my mother."}]'::jsonb, 0),
  ('past-listen', 'en-c3-listening', 'Dinlə və seç: keçmiş iş', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('past-read', 'en-c3-reading', 'Reading: My weekend', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"Last Saturday was a great day. In the morning I cleaned my room and helped my mother. Then we visited my grandmother. She cooked a nice dinner. In the afternoon I played football with my friends. In the evening I watched a film and went to bed early. It was a happy day."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('past-write', 'en-c3-writing', 'Cümlə qur: Past Simple', 'Sözləri düzgün sıraya düz və Past Simple cümləsi qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas — cümlə yuxarıda düzələcək. Keçmişdə fel -ed alır və ya qaydasız dəyişir (played, went, ate)."}]'::jsonb, 0),
  ('q-rule', 'en-c4-grammar', 'Sual və inkar qaydası', 'İngiliscə sual və inkar necə qurulur? Gəl öyrənək!', null, '[{"heading":"Sual necə qurulur?","body":"do/does/did + kim + fel: Do you like tea? Does she play? Did they go? Sual sözü əvvələ gəlir: What do you want?"},{"heading":"İnkar (negatives)","body":"don''t/doesn''t/didn''t + fel: I don''t like. She doesn''t play. We didn''t go."},{"heading":"Sual sözləri","body":"what (nə), where (harada), when (nə vaxt), who (kim), why (niyə), how (necə)."}]'::jsonb, 0),
  ('q-vocab', 'en-c4-vocab', 'Sual sözləri (wh- sözlər)', 'İngiliscə sual verməyə kömək edən 6 sözü öyrənək.', null, '[{"heading":"Yeni sözlər (sual sözləri)","body":"what — nə · where — harada · when — nə vaxt · who — kim · why — niyə · how — necə"},{"heading":"Məsləhət","body":"Bu sözlər cümlənin əvvəlində gəlir: What is your name? Where do you live?"}]'::jsonb, 0),
  ('q-listen', 'en-c4-listening', 'Dinlə və seç: sual-cavab', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('q-read', 'en-c4-reading', 'Reading: An interview', 'Qısa müsahibəni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"This is an interview with Nigar. — What is your name? — My name is Nigar. — Where are you from? — I am from Ganja. — How old are you? — I am eleven. — Do you like school? — Yes, I do. I like English very much. — What is your favourite sport? — I like basketball. — Do you play every day? — No, I don''t. I play on Sundays."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('q-write', 'en-c4-writing', 'Cümlə qur: sual və inkar', 'Sözləri düzgün sıraya düz və sual/inkar cümləsi qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas. Sual: (sual sözü) + do/does/did + kim + fel. İnkar: kim + do/does not + fel."}]'::jsonb, 0)
